/* Own minimal simulator of the Wix cookie banner for integration tests (no vendor code). Mimics public identifiers
   only: window.consentPolicyManager.getCurrentConsentPolicy(), the data-hook attributes of the banner and the cookie
   "consent-policy". The script tag's data-sim-variant says what the first layer offers: "Alle ablehnen" (decline),
   only "Cookie-Einstellungen" and "Zustimmen" (no-decline), "Zustimmen" and the close button alone (close-only), or
   "Zustimmen" and × with the settings control outside the banner (settings-outside). data-sim-policy="throws" makes
   getCurrentConsentPolicy() throw, as a platform whose policy cannot be read.
   The settings control opens the settings layer with one switch per category (the essential one on and disabled) and
   "Speichern", which stores the switches as they are. data-sim-settings says how the layer differs: "preselected"
   (analytics on), "two-saves" (a second save control), "unsaved" (saving closes the layer without storing an answer),
   "hidden-copy" (analytics on, behind a hidden copy of the layer with every switch off that comes first in the page),
   "locked-on" (analytics on and locked like the essential switch).
   Opening the layer loads its stylesheet; accepting or saving a category loads the local fake tracker. */
(function () {
  var script = document.currentScript;
  var variant = (script && script.getAttribute('data-sim-variant')) || 'decline';
  var settingsVariant = (script && script.getAttribute('data-sim-settings')) || 'off';
  var policyFails = !!script && script.getAttribute('data-sim-policy') === 'throws';
  var NAMES = { functional: 'func', analytics: 'anl', advertising: 'adv' };
  var BASE = 'https://static.parastorage.com/services/cookie-consent-banner-for-uou/1.0.0/';

  function readStored() {
    var parts = document.cookie.split(';');
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim();
      if (p.indexOf('consent-policy=') !== 0) continue;
      try { return JSON.parse(decodeURIComponent(p.slice('consent-policy='.length))); } catch (e) { return null; }
    }
    return null;
  }
  var stored = readStored();

  // As on Wix, dataToThirdParty is on before any answer and after either one: the banner does not ask for it.
  function policyOf(s) {
    var policy = { essential: true, dataToThirdParty: !s || s.dt3 === 1 };
    for (var k in NAMES) policy[k] = !!(s && s[NAMES[k]] === 1);
    return policy;
  }
  window.consentPolicyManager = {
    getCurrentConsentPolicy: function () {
      if (policyFails) throw new Error('consent policy unavailable');
      return { defaultPolicy: !stored, policy: policyOf(stored) };
    }
  };

  function loadTracker() {
    var s = document.createElement('script');
    s.src = 'https://stats.wix.test/t.js';
    document.head.appendChild(s);
  }
  function store(choice) {
    stored = { ess: 1, func: choice.func, anl: choice.anl, adv: choice.adv, dt3: 1, ts: Date.now() };
    document.cookie = 'consent-policy=' + encodeURIComponent(JSON.stringify(stored)) + '; path=/; max-age=15552000; SameSite=Lax';
    if (choice.func || choice.anl || choice.adv) loadTracker();
  }
  function save(all) {
    var v = all ? 1 : 0;
    store({ func: v, anl: v, adv: v });
  }

  var btn = 'margin:4px;padding:10px 16px;border:1px solid #116dff;font:14px sans-serif;cursor:pointer;';

  function openSettings(root) {
    var css = document.createElement('link');
    css.rel = 'stylesheet';
    css.href = BASE + 'settings.css';
    document.head.appendChild(css);
    if (root) root.style.display = 'none';
    if (settingsVariant === 'hidden-copy') document.body.appendChild(settingsModal(false, true));
    var preselected = settingsVariant === 'preselected' || settingsVariant === 'hidden-copy';
    var modal = settingsModal(preselected, false);
    document.body.appendChild(modal);

    var saves = modal.querySelectorAll('[data-hook="consent-banner-settings-save-button"]');
    for (var j = 0; j < saves.length; j++) {
      saves[j].addEventListener('click', function () {
        var on = function (key) { return modal.querySelector('[data-sim-group="' + key + '"]').checked ? 1 : 0; };
        if (settingsVariant !== 'unsaved') store({ func: on('func'), anl: on('anl'), adv: on('adv') });
        modal.remove();
        if (root) root.remove();
      });
    }
  }

  function settingsModal(analyticsOn, hidden) {
    var groups = [
      ['Funktionale Cookies', 'func', false],
      ['Analyse-Cookies', 'anl', analyticsOn],
      ['Werbe-Cookies', 'adv', false]
    ];
    var row = 'display:flex;justify-content:space-between;align-items:center;margin:6px 0';
    var html =
      '<h2 id="consent-settings-title" style="margin:0 0 8px;font-size:18px">Cookie-Einstellungen</h2>' +
      '<label style="' + row + '"><span>Erforderliche Cookies</span>' +
      '<input type="checkbox" role="switch" data-sim-group="ess" checked disabled></label>';
    for (var i = 0; i < groups.length; i++) {
      var locked = settingsVariant === 'locked-on' && groups[i][1] === 'anl';
      html += '<label style="' + row + '"><span>' + groups[i][0] + '</span>' +
        '<input type="checkbox" role="switch" data-sim-group="' + groups[i][1] + '"' + (groups[i][2] || locked ? ' checked' : '') + (locked ? ' disabled' : '') + '></label>';
    }
    html += '<div style="text-align:right">' +
      (settingsVariant === 'two-saves'
        ? '<button data-hook="consent-banner-settings-save-button" style="' + btn + 'background:#fff;color:#116dff">Auswahl speichern</button>'
        : '') +
      '<button data-hook="consent-banner-settings-save-button" style="' + btn + 'background:#116dff;color:#fff">Speichern</button></div>';

    var modal = document.createElement('div');
    modal.setAttribute('data-hook', 'consent-banner-settings-modal');
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-labelledby', 'consent-settings-title');
    modal.style.cssText = 'position:fixed;left:0;right:0;bottom:0;z-index:100000;background:#fff;color:#222;box-shadow:0 -2px 8px rgba(0,0,0,.2);padding:16px 48px 16px 24px;font:14px/1.4 sans-serif' +
      (hidden ? ';visibility:hidden' : '');
    modal.innerHTML = html;
    return modal;
  }

  var CLOSE_ICON = 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18" stroke="#000" stroke-width="2"/></svg>');
  function render() {
    var decline = variant === 'decline';
    var root = document.createElement('div');
    root.className = 'consent-banner-root';
    root.setAttribute('data-hook', 'consent-banner-root');
    root.setAttribute('aria-labelledby', 'cookies_policy_description');
    root.setAttribute('role', 'region');
    root.setAttribute('data-comp-type', 'cookie-banner-root-uou');
    root.setAttribute('tabindex', '-1');
    root.style.cssText = 'position:fixed;left:0;right:0;bottom:0;z-index:99999;display:flex;align-items:center;background:#fff;color:#222;box-shadow:0 -2px 8px rgba(0,0,0,.2);padding:8px 48px 8px 24px;font:14px/1.4 sans-serif';
    root.innerHTML =
      '<div class="consent-banner-root-container" style="display:flex;align-items:center;width:100%">' +
      '<div style="flex:1"><span class="consent-banner-description" id="cookies_policy_description" data-hook="consent-banner-description" aria-hidden="true">' +
      'Diese Seite setzt Cookies ein, um ihre Nutzung auszuwerten. Mit „Zustimmen“ erlauben Sie das. ' +
      '<a data-hook="consent-banner-view-policy-link" href="/datenschutz" target="_self">' + (decline ? 'Datenschutzerklärung' : 'Zur Datenschutzerklärung') + '</a></span></div>' +
      '<div class="consent-banner-buttons">' +
      (decline
        ? '<span data-hook="consent-banner-settings-button" role="button" tabindex="0" style="' + btn + 'display:inline-block;border:0;text-decoration:underline">Einstellungen</span>' +
          '<button data-hook="consent-banner-decline-all-button" style="' + btn + 'background:#fff;color:#116dff">Alle ablehnen</button>'
        : variant === 'close-only' || variant === 'settings-outside'
          ? ''
          : '<button data-hook="consent-banner-settings-button" style="' + btn + 'background:#fff;color:#116dff">Cookie-Einstellungen</button>') +
      '<button data-hook="consent-banner-apply-button" style="' + btn + 'background:#116dff;color:#fff">Zustimmen</button>' +
      '</div></div>' +
      '<span class="consent-banner-close-button-container" style="position:absolute;right:8px;top:8px">' +
      '<button data-hook="consent-banner-close-button" aria-label="Schließen" style="border:0;background:none;padding:4px;cursor:pointer">' +
      '<img alt="Schließen" width="24" height="24" src="' + CLOSE_ICON + '"></button></span>';
    document.body.appendChild(root);

    function done(all) { save(all); root.remove(); }
    root.querySelector('[data-hook="consent-banner-apply-button"]').addEventListener('click', function () { done(true); });
    var declineBtn = root.querySelector('[data-hook="consent-banner-decline-all-button"]');
    if (declineBtn) declineBtn.addEventListener('click', function () { done(false); });
    root.querySelector('[data-hook="consent-banner-close-button"]').addEventListener('click', function () { root.remove(); });

    var opener = root.querySelector('[data-hook="consent-banner-settings-button"]');
    if (variant === 'settings-outside') {
      // A settings control of the page itself, outside the banner, with the vendor's hook.
      opener = document.createElement('button');
      opener.setAttribute('data-hook', 'consent-banner-settings-button');
      opener.textContent = 'Cookie-Einstellungen';
      opener.style.cssText = 'position:fixed;left:24px;top:24px;z-index:99998;' + btn;
      document.body.appendChild(opener);
    }
    if (opener) opener.addEventListener('click', function () { openSettings(root); });
  }

  if (stored && stored.anl === 1) loadTracker();
  if (!stored) {
    if (document.body) render();
    else document.addEventListener('DOMContentLoaded', render);
  }
})();
